      const phonePattern = /^\+?[0-9]{1,3}[-\s]?\(?[0-9]{2,4}\)?[-\s]?[0-9]{3,4}[-\s]?[0-9]{3,4}$/;
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      function TextField({ id, label, type, required = false, placeholder, helpText = "", autocomplete = "" }) {
        const describedBy = [helpText ? `${id}-help` : null, `${id}-error`].filter(Boolean).join(" ");
        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              placeholder="${placeholder}"
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              ${required ? "required" : ""}
              aria-describedby="${describedBy}"
            />
            ${helpText ? `<p class="field-help" id="${id}-help">${helpText}</p>` : ""}
            <p class="field-error" id="${id}-error" aria-live="polite"></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <main class="page-shell">
            <section class="contact-card" aria-labelledby="support-title">
              <header class="contact-hero">
                <p class="eyebrow">Support</p>
                <h1 id="support-title">Contact our support team</h1>
                <p class="lead">Send us your details and we will follow up as soon as possible.</p>
              </header>
              <form id="support-form" novalidate>
                <div class="form-grid">
                  ${TextField({
                    id: "fullName",
                    label: "Full name",
                    type: "text",
                    required: true,
                    placeholder: "Jane Doe",
                    autocomplete: "name",
                  })}
                  ${TextField({
                    id: "emailAddress",
                    label: "Email address",
                    type: "email",
                    required: true,
                    placeholder: "jane@company.com",
                    autocomplete: "email",
                  })}
                  ${TextField({
                    id: "phoneNumber",
                    label: "Phone number",
                    type: "tel",
                    placeholder: "+1 555 123 4567",
                    helpText: "Optional. Use a number like +1 555 123 4567 or 555-123-4567.",
                    autocomplete: "tel",
                  })}
                </div>
                <div class="actions">
                  <button type="submit">Submit</button>
                </div>
              </form>
            </section>
          </main>
        `;
      }

      function setError(input, message) {
        const error = document.getElementById(`${input.id}-error`);
        input.setAttribute("aria-invalid", message ? "true" : "false");
        error.textContent = message;
      }

      function validateField(input) {
        const value = input.value.trim();

        if (input.id === "fullName") {
          if (!value) return "Full name is required.";
          if (value.length < 2) return "Please enter a valid full name.";
          return "";
        }

        if (input.id === "emailAddress") {
          if (!value) return "Email address is required.";
          if (!emailPattern.test(value)) return "Enter a valid email address.";
          return "";
        }

        if (input.id === "phoneNumber" && value && !phonePattern.test(value)) {
          return "Enter a valid phone number format.";
        }

        return "";
      }

      document.getElementById("app").innerHTML = ContactForm();

      const form = document.getElementById("support-form");
      const fields = ["fullName", "emailAddress", "phoneNumber"].map((id) => document.getElementById(id));

      fields.forEach((field) => {
        field.addEventListener("input", () => setError(field, validateField(field)));
        field.addEventListener("blur", () => setError(field, validateField(field)));
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let firstInvalid = null;
        fields.forEach((field) => {
          const message = validateField(field);
          setError(field, message);
          if (message && !firstInvalid) firstInvalid = field;
        });

        if (firstInvalid) {
          firstInvalid.focus();
          return;
        }

        form.reset();
        fields.forEach((field) => setError(field, ""));
      });
    </script>
  </body>
